-- Shorten pasted bios: keep the original in about_paragraphs when empty.
UPDATE public.brands AS b
SET
  about_paragraphs = CASE
    WHEN coalesce(cardinality(b.about_paragraphs), 0) = 0
      AND b.short_description IS NOT NULL
      AND length(btrim(b.short_description)) > 220
    THEN ARRAY[btrim(b.short_description)]
    ELSE b.about_paragraphs
  END,
  short_description = v.short_description,
  updated_at = now()
FROM (VALUES
  ('1-DA Shapes', 'High-performance shortboards from Gavin Upson in Tweed Heads — contest-tested epoxy and PU shapes.'),
  ('1-Da Shapes', 'High-performance shortboards from Gavin Upson in Tweed Heads — contest-tested epoxy and PU shapes.'),
  ('11th Street Surfboards', 'Father-and-son epoxy surfboards from Florida — built heavy enough to last, light enough to fly.'),
  ('FCS', 'Removable surfboard fins, traction, and hardware from Fin Control Systems.'),
  ('Trimcraft', 'A crew of hand shapers building 100% hand-shaped surfboards in California, Florida, New Jersey, and Portugal.')
) AS v(name, short_description)
WHERE b.name = v.name
  AND b.short_description IS NOT NULL
  AND btrim(b.short_description) <> v.short_description
  AND length(btrim(b.short_description)) > 160;

